    for kind, name in [('GEOMETRY', 'Carriers'), ('FLOAT', 'Width'), ('BOOLEAN', 'Valid')]:
        ro.repeat_items.new(kind, name)
    if fit_style_radii:ro.repeat_items.new('GEOMETRY','Contact budgets')
    ri.pair_with_output(ro)
    g.link(h.switch(source_valid, 0, count.outputs['Instance Count'], 'INT'), ri.inputs['Iterations'])
