    stats = g.node('GeometryNodeAttributeStatistic', 'Largest complete Section width'); stats.domain = 'EDGE'; stats.data_type = 'FLOAT'
    g.link(sources, stats.inputs['Geometry']); g.link(g.named('st_width', 'FLOAT'), stats.inputs['Attribute'])
    g.link(h.all(h.compare(width, .001, 'GREATER_THAN'), h.compare(width, 1000., 'LESS_EQUAL')), stats.inputs['Selection'])
