    local = local_instance(collection.outputs['Instances'], ri.outputs['Iteration'], 'One original local template')
    live = g.node('GeometryNodeGroup', 'Read actual terminal edges'); live.node_tree = live_input_nodes.build()
    g.link(sources, live.inputs['Sources']); g.link(local, live.inputs['Carrier'])
