    g.link(ri.outputs['Carriers'], instances.inputs['Geometry']); g.link(instance.outputs['Instances'], instances.inputs['Geometry'])
    g.link(instances.outputs['Geometry'], ro.inputs['Carriers'])
    g.link(g.both(ri.outputs['Valid'], live.outputs['Valid']), ro.inputs['Valid'])
    carriers=ro.outputs['Carriers']
    if fit_style_radii:
        from . import corner_radius_budget_nodes
        contacts=g.node('GeometryNodeGroup','Measure preferred and minimum style contacts')
        contacts.node_tree=corner_radius_budget_nodes.collect()
        for key,value in (('Sources',sources),('Carrier',tagged_carrier),('Prepared',prep.outputs['Geometry'])):
            g.link(value,contacts.inputs[key])
