        g.link(ri.outputs['Contact budgets'],contact_join.inputs['Geometry'])
        g.link(contacts.outputs['Geometry'],contact_join.inputs['Geometry'])
        g.link(contact_join.outputs['Geometry'],ro.inputs['Contact budgets'])
        factors=g.node('GeometryNodeGroup','Pair both ends of each complete straight Section')
