    allocation_valid = h.all(source_valid, h.compare(nv, 256, 'LESS_EQUAL'))
    nv = h.math('MINIMUM', 256, nv)

    ji = g.node('GeometryNodeRepeatInput', 'Generate all intersections with common sampling')
